<div class="section-head"><div><h2>User administration</h2><p class="muted">Search accounts, control status, and assign roles.</p></div><form method="get" class="inline-form"><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Name or email"><button class="button">Search</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Institution</th><th>Roles</th><th>Rating</th><th>Account control</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['user_name'])?></strong><br><?=e($u['email'])?></td><td><?=e($u['institution']??'—')?></td><td><?=e($u['roles'])?></td><td><?=e($u['rating'])?></td><td><form method="post" action="<?=e(url('/admin/users/'.$u['user_id']))?>" class="inline-form"><?=csrf_field()?><select name="status"><?php foreach(['ACTIVE','SUSPENDED','DISABLED'] as $s):?><option <?=$u['account_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><select name="role"><?php foreach(['PARTICIPANT','ORGANIZER','ADMIN'] as $r):?><option><?=e($r)?></option><?php endforeach;?></select><button class="button-small button">Update</button></form></td></tr><?php endforeach;?><?php if(!$users):?><tr><td colspan="5" class="empty">No users found.</td></tr><?php endif;?></tbody></table></div>
